static uint32_t lookup_pair(const void *arr, size_t n, uint32_t key, uint32_t dflt) {
    const struct { uint32_t a; uint32_t b; } *p = arr;
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (p[mid].a < key) lo = mid + 1;
        else if (p[mid].a > key) hi = mid;
        else return p[mid].b;
    }
    return dflt;
}

static int parse_hex_exact(const char *s, uint32_t *out) {
    if (!*s) return 0;
    uint64_t v = 0;
    size_t len = 0;
    for (const char *p = s; *p; p++, len++) {
        unsigned char c = (unsigned char)*p;
        uint32_t d;
        if (c >= '0' && c <= '9') d = (uint32_t)(c - '0');
        else if (c >= 'a' && c <= 'f') d = (uint32_t)(c - 'a' + 10);
        else if (c >= 'A' && c <= 'F') d = (uint32_t)(c - 'A' + 10);
        else return 0;
        if (len >= 16) return 0;
        v = (v << 4) | d;
        if (v > 0xffffffffULL) return 0;
    }
    *out = (uint32_t)v;
    return 1;
}

static txkb_keysym_t lookup_name_exact(const char *name) {
    size_t lo = 0, hi = sizeof(name_to_keysym) / sizeof(name_to_keysym[0]);
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        int cmp = strcmp(keysym_names_pool + name_to_keysym[mid].a, name);
        if (cmp < 0) lo = mid + 1;
        else if (cmp > 0) hi = mid;
        else return name_to_keysym[mid].b;
    }
    return TXKB_KEY_NoSymbol;
}

static txkb_keysym_t lookup_name_ci(const char *name) {
    size_t n = strlen(name);
    if (n >= 64) return TXKB_KEY_NoSymbol;
    char lower[64];
    for (size_t i = 0; i <= n; i++) {
        unsigned char c = (unsigned char)name[i];
        lower[i] = (c >= 'A' && c <= 'Z') ? (char)(c + ('a' - 'A')) : (char)c;
    }
    size_t lo = 0, hi = sizeof(ci_to_keysym) / sizeof(ci_to_keysym[0]);
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        int cmp = strcmp(keysym_names_pool + ci_to_keysym[mid].a, lower);
        if (cmp < 0) lo = mid + 1;
        else if (cmp > 0) hi = mid;
        else return ci_to_keysym[mid].b;
    }
    return TXKB_KEY_NoSymbol;
}

int txkb_keysym_get_name(txkb_keysym_t ks, char *buffer, size_t size) {
    if (ks > 0x1fffffffU) {
        snprintf(buffer, size, "Invalid");
        return -1;
    }
    if (ks == 0) {
        return snprintf(buffer, size, "NoSymbol");
    }
    uint32_t off = lookup_pair(keysym_to_name,
        sizeof(keysym_to_name) / sizeof(keysym_to_name[0]), ks, 0xffffffffU);
    if (off != 0xffffffffU) {
        return snprintf(buffer, size, "%s", keysym_names_pool + off);
    }
    if (ks >= 0x01000100U && ks <= 0x0110ffffU) {
        return snprintf(buffer, size, "U%04X", ks & 0xffffffU);
    }
    return snprintf(buffer, size, "0x%08x", ks);
}

txkb_keysym_t txkb_keysym_from_name(const char *name, enum txkb_keysym_flags flags) {
    if (!name || !*name) return TXKB_KEY_NoSymbol;
    if (strcmp(name, "NoSymbol") == 0) return TXKB_KEY_NoSymbol;
    int ci = (flags & TXKB_KEYSYM_CASE_INSENSITIVE) != 0;
    if (ci && lookup_name_ci(name) == TXKB_KEY_NoSymbol && strcmp(name, "nosymbol") == 0)
        return TXKB_KEY_NoSymbol;

    txkb_keysym_t ks = ci ? lookup_name_ci(name) : lookup_name_exact(name);
    if (ks != TXKB_KEY_NoSymbol) return ks;

    if ((name[0] == 'X' || (ci && name[0] == 'x')) &&
        (name[1] == 'F' || (ci && name[1] == 'f')) &&
        name[2] == '8' && name[3] == '6' && name[4] == '_') {
        size_t n = strlen(name);
        if (n < 128) {
            char alt[128];
            memcpy(alt, name, 4);
            memcpy(alt + 4, name + 5, n - 4);
            ks = ci ? lookup_name_ci(alt) : lookup_name_exact(alt);
            if (ks != TXKB_KEY_NoSymbol) return ks;
        }
    }

    if ((name[0] == 'U' || (ci && name[0] == 'u')) && name[1] != '\0') {
        uint32_t cp = 0;
        if (!parse_hex_exact(name + 1, &cp)) return TXKB_KEY_NoSymbol;
        if (cp == 0 || cp > 0x10ffffU) return TXKB_KEY_NoSymbol;
        if ((cp >= 0x20U && cp <= 0x7eU) || (cp >= 0xa0U && cp <= 0xffU)) return cp;
        switch (cp) {
        case 0x08U: return 0xff08U;
        case 0x09U: return 0xff09U;
        case 0x0aU: return 0xff0aU;
        case 0x0bU: return 0xff0bU;
        case 0x0dU: return 0xff0dU;
        case 0x1bU: return 0xff1bU;
        case 0x7fU: return 0xffffU;
        default: return cp | 0x01000000U;
        }
    }

    if (name[0] == '0' && (name[1] == 'x' || (ci && name[1] == 'X'))) {
        uint32_t val = 0;
        if (!parse_hex_exact(name + 2, &val)) return TXKB_KEY_NoSymbol;
        if (val <= 0x1fffffffU) return val;
        return TXKB_KEY_NoSymbol;
    }

    return TXKB_KEY_NoSymbol;
}

uint32_t txkb_keysym_to_utf32(txkb_keysym_t ks) {
    if (ks < 0x01000000U) {
        return lookup_pair(legacy_utf32_map,
            sizeof(legacy_utf32_map) / sizeof(legacy_utf32_map[0]), ks, 0U);
    }
    if (ks > 0x01000000U && ks <= 0x0110ffffU) {
        uint32_t cp = ks & 0xffffffU;
        if (cp >= 0xd800U && cp <= 0xdfffU) return 0U;
        return cp;
    }
    return 0U;
}

int txkb_keysym_to_utf8(txkb_keysym_t ks, char *buffer, size_t size) {
    uint32_t cp = txkb_keysym_to_utf32(ks);
    char tmp[5];
    size_t len = 0;
    if (cp == 0U) {
        if (size < 1U) return -1;
        buffer[0] = '\0';
        return 0;
    } else if (cp < 0x80U) {
        tmp[0] = (char)cp;
        len = 1U;
    } else if (cp < 0x800U) {
        tmp[0] = (char)(0xc0U | (cp >> 6));
        tmp[1] = (char)(0x80U | (cp & 0x3fU));
        len = 2U;
    } else if (cp < 0x10000U) {
        tmp[0] = (char)(0xe0U | (cp >> 12));
        tmp[1] = (char)(0x80U | ((cp >> 6) & 0x3fU));
        tmp[2] = (char)(0x80U | (cp & 0x3fU));
        len = 3U;
    } else {
        tmp[0] = (char)(0xf0U | (cp >> 18));
        tmp[1] = (char)(0x80U | ((cp >> 12) & 0x3fU));
        tmp[2] = (char)(0x80U | ((cp >> 6) & 0x3fU));
        tmp[3] = (char)(0x80U | (cp & 0x3fU));
        len = 4U;
    }
    if (size < len + 1U) {
        if (size >= 4U) memcpy(buffer, "Inv", 4U);
        else if (size > 0U) memcpy(buffer, "Inv", size - 1U), buffer[size - 1U] = '\0';
        return -1;
    }
    memcpy(buffer, tmp, len);
    buffer[len] = '\0';
    return (int)(len + 1U);
}

txkb_keysym_t txkb_utf32_to_keysym(uint32_t cp) {
    if (cp == 0U || cp > 0x10ffffU || (cp >= 0xd800U && cp <= 0xdfffU))
        return TXKB_KEY_NoSymbol;
    if ((cp >= 0x20U && cp <= 0x7eU) || (cp >= 0xa0U && cp <= 0xffU))
        return cp;
    switch (cp) {
    case 0x08U: return 0xff08U;
    case 0x09U: return 0xff09U;
    case 0x0aU: return 0xff0aU;
    case 0x0bU: return 0xff0bU;
    case 0x0dU: return 0xff0dU;
    case 0x1bU: return 0xff1bU;
    case 0x7fU: return 0xffffU;
    default: break;
    }
    uint32_t mapped = lookup_pair(utf32_to_keysym_map,
        sizeof(utf32_to_keysym_map) / sizeof(utf32_to_keysym_map[0]), cp, 0xffffffffU);
    if (mapped != 0xffffffffU) return mapped;
    return cp | 0x01000000U;
}

txkb_keysym_t txkb_keysym_to_lower(txkb_keysym_t ks) {
    if (ks >= 0x01110000U) return ks;
    return lookup_pair(lower_map, sizeof(lower_map) / sizeof(lower_map[0]), ks, ks);
}

txkb_keysym_t txkb_keysym_to_upper(txkb_keysym_t ks) {
    if (ks >= 0x01110000U) return ks;
    return lookup_pair(upper_map, sizeof(upper_map) / sizeof(upper_map[0]), ks, ks);
}


