static bool in_u32_ranges(const uint32_t tbl[][2], size_t n, uint32_t cp) {
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2U;
        if (cp < tbl[mid][0]) hi = mid;
        else if (cp > tbl[mid][1]) lo = mid + 1U;
        else return true;
    }
    return false;
}

bool txkb_keysym_is_lower(txkb_keysym_t ks) {
    if (ks >= 0x01000000U && ks < 0x01000100U) return false;
    uint32_t cp = txkb_keysym_to_utf32(ks);
    if (cp == 0U) return false;
    return in_u32_ranges(utf32_lower_ranges,
        sizeof(utf32_lower_ranges) / sizeof(utf32_lower_ranges[0]), cp);
}

bool txkb_keysym_is_upper(txkb_keysym_t ks) {
    if (ks >= 0x01000000U && ks < 0x01000100U) return false;
    uint32_t cp = txkb_keysym_to_utf32(ks);
    if (cp == 0U) return false;
    return in_u32_ranges(utf32_upper_ranges,
        sizeof(utf32_upper_ranges) / sizeof(utf32_upper_ranges[0]), cp);
}
